package com.kitchensync.app

data class Member(val uid: String = "", val name: String = "", val approved: Boolean = false)
data class Item(
    val id: String = "", val name: String = "", val category: String = "",
    val qty: Double = 1.0, val unit: String = "шт", val noQty: Boolean = false,
    val expiry: Long = 0L, val low: Double = 1.0
)
data class Shop(val id: String = "", val name: String = "", val forDish: String = "", val done: Boolean = false, val amount: Double = 0.0, val unit: String = "")
data class Cooked(
    val id: String = "", val dish: String = "", val byUid: String = "", val byName: String = "",
    val ts: Long = 0L, val ratings: Map<String, Long> = emptyMap()
)
data class Ing(val name: String = "", val perPerson: Double = 0.0, val unit: String = "", val note: String = "")
data class Dish(val name: String = "", val category: String = "", val ings: List<Ing> = emptyList(), val steps: List<String> = emptyList(), val id: String = "", val persons: Int = 0, val cook: Boolean = false, val minutes: Int = 0, val origin: String = "")
data class DayPlan(val dishes: List<Dish> = emptyList())
data class SavedMenu(val id: String = "", val name: String = "", val persons: Int = 2, val days: List<DayPlan> = emptyList())

fun unitGroup(u: String) = when (u) { "кг", "г" -> 1; "л", "мл" -> 2; else -> 3 }
fun baseQty(q: Double, u: String) = if (u == "кг" || u == "л") q * 1000 else q
fun stepFor(u: String) = when (u) { "г", "мл" -> 100.0; "кг", "л" -> 0.5; else -> 1.0 }
fun fmt(d: Double): String = if (d % 1.0 == 0.0) d.toInt().toString() else "%.2f".format(d).trimEnd('0').trimEnd('.')
fun pers(n: Int) = if (n % 10 == 1 && n % 100 != 11) "особа" else if (n % 10 in 2..4 && n % 100 !in 12..14) "особи" else "осіб"

/** How much of an ingredient is missing in the fridge (in the ingredient's unit). */
fun shortage(items: List<Item>, ing: Ing, persons: Int): Double {
    val need = ing.perPerson * persons
    val have = items.firstOrNull { it.name.trim().equals(ing.name.trim(), true) } ?: return need
    if (have.noQty) return 0.0
    if (unitGroup(have.unit) != unitGroup(ing.unit)) return if (have.qty <= 0) need else 0.0
    val diff = baseQty(need, ing.unit) - baseQty(have.qty, have.unit)
    if (diff <= 0.0) return 0.0
    return if (ing.unit == "кг" || ing.unit == "л") diff / 1000 else diff
}
fun isMissing(items: List<Item>, ing: Ing, persons: Int): Boolean = shortage(items, ing, persons) > 0.0

