fun fmtTime(m: Int) = if (m < 60) "$m хв" else if (m % 60 == 0) "${m / 60} год" else "${m / 60} год ${m % 60} хв"
fun timeOf(d: Dish): Int = if (d.minutes > 0) d.minutes else (TIMES[d.name] ?: 0)
fun originOf(d: Dish): String = d.origin.ifBlank { ORIGINS[d.name] ?: "" }
fun metaOf(d: Dish): String = listOfNotNull(
    d.category,
    timeOf(d).takeIf { it > 0 }?.let { "⏱ " + fmtTime(it) },
    originOf(d).takeIf { it.isNotBlank() }?.let { "🌍 $it" }
).joinToString(" · ")
fun ingText(ing: Ing, p: Int): String =
    if (ing.perPerson > 0.0) "${ing.name} — ${fmt(ing.perPerson * p)} ${ing.unit}"
    else ing.name + (if (ing.note.isNotBlank()) " — ${ing.note}" else "")

private fun dish(name: String, cat: String, min: Int, origin: String, ings: String, vararg steps: String) = Dish(
    name = name, category = cat, minutes = min, origin = origin, steps = steps.toList(),
    ings = ings.split(";").map { val p = it.split(":"); Ing(p[0], p[1].toDouble(), p[2]) }
)

